// Renders docs/CARD_INDEX.md: every card id and title, by topic. It lets a
// contributor see what the deck already covers in one read, without opening
// every pack.
export function renderCardIndex({ topics, facts }) {
  const lines = [
    '# Card index',
    '',
    `Every card in the deck: ${facts.length} cards across ${topics.length} topics. Read this before writing new cards so you do not repeat one.`,
    '',
    'Generated by `npm run sync`. Do not edit by hand. `content/` is the source of truth.',
    '',
  ]
  for (const topic of topics) {
    const cards = facts.filter((fact) => fact.category === topic.id)
    lines.push(`## ${topic.name} (\`${topic.id}\`, ${cards.length} cards)`, '')
    for (const card of cards) lines.push(`- \`${card.id}\` ${card.title}`)
    lines.push('')
  }
  return lines.join('\n')
}
